# Code snippet to check for potential security issues in zip file contents
import zipfile
import io

def check_zip_contents(zip_bytes):
    try:
        with zipfile.ZipFile(io.BytesIO(zip_bytes)) as zip_file:
            for zip_info in zip_file.infolist():
                print(f"File: {zip_info.filename}, Size: {zip_info.file_size} bytes")
                if zip_info.filename.startswith('/') or '..' in zip_info.filename:
                    print("Potential directory traversal attack detected!")
    except zipfile.BadZipFile:
        print("Invalid zip file.")

